window.VF2_UNITS = {"9":{"unit":9,"code":"VF2-U09","title":"EDUCATION & LEARNING","startNumber":164,"endNumber":185,"entries":[{"number":164,"term":"qualification (n) # quality (n)","spoken":"qualification , quality","ipa":"qualification /ˌkwɑːləfəˈkeɪʃən/ · quality /ˈkwɑːləti/","type":"noun · word family","meaning":"bằng cấp/năng lực chuyên môn # chất lượng/phẩm chất","definition":"A qualification proves training or ability; quality means a standard or personal characteristic.","note":"qualification là bằng cấp/năng lực được chứng nhận; quality là chất lượng hoặc phẩm chất.","example":"A teaching qualification proves professional training, whereas quality describes how good the teaching is."},{"number":165,"term":"degree (n) ~ diploma (n) · high school diploma # licence/license (n) · driving licence/license ~ permit (n) · work permit","spoken":"degree , diploma , high school diploma , licence or license , driving licence or license , permit , work permit","ipa":"degree /dɪˈɡriː/ · diploma /dɪˈploʊmɑ/ · high /haɪ/ · school /skuːl/ · licence /ˈlaɪsəns/ · license /ˈlaɪsəns/ · driving /ˈdraɪvɪŋ/ · permit /ˈpɝːmɪt/ · work /wɝːk/","type":"noun · word family","meaning":"bằng đại học ~ văn bằng/chứng chỉ · bằng tốt nghiệp trung học # giấy phép · giấy phép lái xe ~ giấy phép cho một hoạt động · giấy phép lao động","definition":"A degree or diploma is an educational award; a licence or permit gives official permission for an activity.","note":"degree thường là bằng đại học; diploma là văn bằng; licence/license và permit đều là giấy phép nhưng dùng theo loại hoạt động.","example":"She earned a university degree, holds a high-school diploma, and needs a work permit to take the job."},{"number":166,"term":"attend (v) st · attendance (n) # attend (v) to sb/st · attention (n) · draw sb's attention to st","spoken":"attend something , attendance , attend to somebody or something , attention , draw somebody's attention to something","ipa":"attend /əˈtɛnd/ · attendance /əˈtɛndəns/ · attention /əˈtɛnʃən/ · draw /drɔː/","type":"verb · noun · phrase / pattern · word family","meaning":"tham dự điều gì · sự có mặt/chuyên cần # chăm sóc/xử lí ai hoặc việc gì · sự chú ý · khiến ai chú ý đến điều gì","definition":"Attend something means be present; attend to means deal with; attention is focused notice.","note":"attend + sự kiện/lớp; attend to = xử lí/chăm sóc; attention là danh từ.","example":"Students attend the lecture, while staff attend to technical problems and draw attention to key evidence."},{"number":167,"term":"make up one’s mind · be in two minds about st · to my mind ~ in my opinion · cross one’s mind · bear st in mind","spoken":"make up one’s mind , be in two minds about something , to my mind , in my opinion , cross one’s mind , bear something in mind","ipa":"make /meɪk/ · up /ʌp/ · mind /maɪnd/ · two /tuː/ · minds /maɪndz/ · about /əˈbaʊt/ · my /maɪ/ · opinion /əˈpɪnjən/ · cross /krɔːs/ · bear /bɛr/","type":"phrase / pattern","meaning":"đưa ra quyết định · phân vân về điều gì · theo ý kiến của tôi ~ theo quan điểm của tôi · nảy ra trong đầu · ghi nhớ khi cân nhắc","definition":"These expressions with mind describe deciding, being uncertain, giving an opinion, thinking of something briefly, or remembering something while deciding.","note":"make up one's mind là quyết định; be in two minds là phân vân; to my mind gần nghĩa với in my opinion; cross one's mind là chợt nghĩ đến; bear something in mind là ghi nhớ khi cân nhắc","example":"The idea crossed her mind while she was in two minds about the course; to my mind, she should bear the deadline in mind before making up her mind."},{"number":168,"term":"There is no point (in) V-ing ~ It is no use V-ing","spoken":"There is no point (in) doing , It is no use doing","ipa":"there /ðɛr/ · is /ɪz/ · no /noʊ/ · point /pɔɪnt/ · it /ɪt/ · use /juːs/","type":"phrase / pattern · word family","meaning":"vô ích, vô nghĩa khi làm gì","definition":"Used to say that an action has no useful purpose.","note":"There is no point (in) V-ing và It is no use V-ing đều theo sau bằng V-ing.","example":"There is no point memorizing a rule if students never use it in context."},{"number":169,"term":"make sense # a sense of + noun","spoken":"make sense , a sense of + noun","ipa":"make /meɪk/ · sense /sɛns/ · noun /naʊn/","type":"phrase / pattern · word family","meaning":"có lí/dễ hiểu · ý thức/cảm nhận về một điều","definition":"Make sense means be understandable; a sense of something can describe an awareness or personal quality.","note":"make sense là có lí hoặc dễ hiểu; a sense of + noun diễn tả ý thức hoặc cảm nhận về một phẩm chất","example":"The explanation makes sense, and a strong sense of responsibility helps learners work independently."},{"number":170,"term":"boast (v) of/about st","spoken":"boast of or about something","ipa":"boast /boʊst/ · about /əˈbaʊt/","type":"verb · phrase / pattern","meaning":"khoe khoang, khoác lác…","definition":"To speak too proudly about achievements or possessions.","note":"Giữ đúng mẫu từ đi kèm: boast (v) of/about st.","example":"The student boasted about his result, although the group project depended on everyone's effort."},{"number":171,"term":"capable of V-ing ~ able to V","spoken":"capable of doing , able to verb","ipa":"capable /ˈkeɪpəbəl/ · able /ˈeɪbəl/","type":"phrase / pattern · word family","meaning":"có khả năng làm gì","definition":"Having the ability needed to do something; followed by of plus an -ing form.","note":"capable of V-ing; able to V. Không dùng capable to V.","example":"She is capable of analysing complex evidence and is able to explain it clearly."},{"number":172,"term":"failure (n)","spoken":"failure","ipa":"failure /ˈfeɪljɚ/","type":"noun","meaning":"thất bại; sự thất bại","definition":"A lack of success, or an unsuccessful person, action, or system.","note":"failure /ˈfeɪljɚ/: phần -ure không đọc tách thành một âm tiết /jʊər/ đầy đủ.","example":"Failure can provide useful feedback when learners examine why an approach did not work."},{"number":173,"term":"intense (a) ~ extreme (a) · intensity (n)","spoken":"intense , extreme , intensity","ipa":"intense /ˌɪˈntɛns/ · extreme /ɛˈkstriːm/ · intensity /ɪˈntɛnsəti/","type":"noun · adjective · word family","meaning":"mãnh liệt/cực độ · cường độ","definition":"Very strong or extreme; intensity is the degree of strength.","note":"","example":"The course requires intense study, and the intensity increases before the final examination."},{"number":174,"term":"literate (a) >< illiterate (a) · literacy (n) >< illiteracy (n) # literal (a) # literary (a) · literature (n)","spoken":"literate , illiterate , literacy , illiteracy , literal , literary , literature","ipa":"literate /ˈlɪtɚət/ · illiterate /ˌɪˈlɪtɚət/ · literacy /ˈlɪtɚəsi/ · illiteracy /ˌɪˈlɪtɚəsi/ · literal /ˈlɪtɚəl/ · literary /ˈlɪtɚˌɛri/ · literature /ˈlɪtɚətʃɚ/","type":"noun · adjective · word family","meaning":"biết chữ >< mù chữ · khả năng biết đọc viết >< tình trạng mù chữ # theo nghĩa đen # thuộc văn chương · văn học","definition":"Literate relates to reading and writing; literal means exact, while literary and literature relate to written art.","note":"literal = theo nghĩa đen; literary = thuộc văn chương; literature = văn học. Đây là nhóm dễ nhầm chữ.","example":"Literacy supports learning; literal meaning differs from literary language and the study of literature."},{"number":175,"term":"scholar (n)","spoken":"scholar","ipa":"scholar /ˈskɑːlɚ/","type":"noun","meaning":"học giả, người nghiên cứu","definition":"A highly educated person who studies a subject in depth.","note":"","example":"The visiting scholar has published research on second-language learning and memory."},{"number":176,"term":"studious (a)","spoken":"studious","ipa":"studious /ˈstuːdiəs/","type":"adjective","meaning":"chăm học","definition":"Spending a lot of time studying and showing serious academic interest.","note":"","example":"A studious learner works consistently but also chooses effective study methods."},{"number":177,"term":"thought (n) · thinking (n)","spoken":"thought , thinking","ipa":"thought /θɔːt/ · thinking /ˈθɪŋkɪŋ/","type":"noun · word family","meaning":"một ý nghĩ · quá trình/cách tư duy","definition":"A thought is a particular idea; thinking is the process of forming and examining ideas.","note":"thought là một ý nghĩ/sản phẩm suy nghĩ; thinking là quá trình/cách tư duy.","example":"A thought may be brief, while critical thinking is a deliberate process of analysing evidence."},{"number":178,"term":"catch on","spoken":"catch on","ipa":"catch /kætʃ/","type":"phrasal verb","meaning":"trở nên phổ biến · hiểu ra","definition":"To understand something, or to become popular.","note":"catch on có thể là trở nên phổ biến hoặc hiểu ra; tân ngữ/ngữ cảnh quyết định.","example":"The new revision method caught on quickly after students realized that it saved time."},{"number":179,"term":"come round to st","spoken":"come round to something","ipa":"come /kʌm/ · round /raʊnd/","type":"phrasal verb","meaning":"dần đồng ý với điều gì sau khi được thuyết phục","definition":"To eventually accept an idea after discussion or persuasion.","note":"Giữ đúng mẫu từ đi kèm: come round to st.","example":"He eventually came round to the teacher's view after examining the data."},{"number":180,"term":"(It) dawn on sb that … · dawn (n)","spoken":"(It) dawn on somebody that … , dawn","ipa":"dawn /dɔːn/ · that /ðæt/","type":"noun · phrase / pattern · word family","meaning":"ai đó chợt hiểu ra rằng… · bình minh","definition":"For an idea or fact to suddenly become clear to somebody; dawn also means first light.","note":"It dawned on sb that... = ai đó chợt hiểu ra; dawn (n) theo nghĩa đen là bình minh.","example":"It dawned on her that the two sources reported the same event from different perspectives."},{"number":181,"term":"get at","spoken":"get at","ipa":"get /ɡɛt/","type":"phrase / pattern","meaning":"ám chỉ…","definition":"To indirectly suggest or imply something.","note":"","example":"I understand the facts, but I am not sure what the writer is getting at."},{"number":182,"term":"give in","spoken":"give in","ipa":"give /ɡɪv/","type":"phrasal verb","meaning":"đầu hàng, nhượng bộ","definition":"To stop resisting and agree to what somebody wants.","note":"","example":"The group refused to give in and continued searching for a better solution."},{"number":183,"term":"drop out (of)","spoken":"drop out (of)","ipa":"drop /drɑːp/ · out /aʊt/","type":"phrasal verb","meaning":"bỏ (học, cuộc thi…)","definition":"To leave a course, school, or competition before completing it.","note":"","example":"Several students dropped out of the course because they could not manage the workload."},{"number":184,"term":"sail through st","spoken":"sail through something","ipa":"sail /seɪl/ · through /θruː/","type":"phrasal verb","meaning":"vượt qua dễ dàng","definition":"To pass or complete something difficult very easily.","note":"Giữ đúng mẫu từ đi kèm: sail through st.","example":"She sailed through the interview because she had prepared detailed examples."},{"number":185,"term":"set out ideas","spoken":"set out ideas","ipa":"set /sɛt/ · out /aʊt/ · ideas /aɪˈdiːəz/","type":"phrasal verb","meaning":"trình bày và sắp xếp các ý tưởng rõ ràng","definition":"To present and organize ideas clearly, usually in speech or writing.","note":"","example":"The introduction sets out the main ideas before the essay develops each one."}],"pronunciationFocus":[{"entryNumber":164,"points":[{"category":"word-stress","note":"qualification /ˌkwɑːləfəˈkeɪʃən/: trọng âm chính đặt ở /keɪ/"}]},{"entryNumber":170,"points":[{"category":"final-sound","note":"boast /boʊst/: giữ đủ cụm âm cuối /st/"}]},{"entryNumber":172,"points":[{"category":"common-error","note":"failure /ˈfeɪljɚ/: phần -ure không tạo thêm một âm tiết riêng"}]},{"entryNumber":183,"points":[{"category":"linking","note":"drop‿out: nối /p/ sang /aʊ/"}]}]}};
